        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfterInit;
        c.SetMinSum(valAfter); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedAfterInit = true;
        } else {
            revertedAfterInit = false;
        }

        bool revertedLogAfterInit;
        c.SetLogFile(logAfter); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
