contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 valBefore, uint256 valAfter, address logBefore, address logAfter) internal {
        try c.SetMinSum(valBefore) {} catch { return; }
        try c.SetLogFile(logBefore) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedAfterInit;
        try c.SetMinSum(valAfter) {
            revertedAfterInit = false;
        } catch {
            revertedAfterInit = true;
        }
        bool revertedLogAfterInit;
        try c.SetLogFile(logAfter) {
            revertedLogAfterInit = false;
        } catch {
            revertedLogAfterInit = true;
        }
        assertTrue(revertedAfterInit && revertedLogAfterInit);
    }

